(* LPS revision repair (75d69e00, checker 2c6b6db8).  rs_model written out as explicit text
   (rule 11; never re-encoded), transcribed from `Print rs_model` of the encoded definition in
   a farm round, with EXACTLY ONE conjunct changed: vm_maps was
     vm_maps h' = map_remove (vm_maps h) (wz a)
   which is what munmap_modelL produced BEFORE the revision.  At 75d69e00 it produces
   maps_subtract (LazyLedger.v:567-572), and the two are NOT equal: LazyLedger.v:541
   maps_subtract_rm_nz gives equality only under a `nz_at` filter, and nz_at (:456) drops the
   ZERO-SIZE entries based at a + msz, which nothing rules out - entry_nowrap is `hi e <= 2^64`
   and nooverlap's `hi e <= lo e' \/ hi e' <= lo e` is satisfied BOTH ways by an empty interval
   (all four printed in a farm round).  So the old claim is false at the
   revision, not merely unproved.
   The intended form is the file's own next conjunct: vm_noaccess already reads
   `maps_subtract (vm_noaccess h) a (a + msz)`, i.e. this definition was half-ported.
   The definition carries no address and no literal, and is character-identical on both sides. *)
Definition rs_model (mo : Model) (a msz : Z) (mo' : Model) : Prop :=
  let h := m_vmmaps mo in let h' := m_vmmaps mo' in
     nonvm_same mo mo'
  /\ vm_maps h' = maps_subtract (vm_maps h) a (a + msz)
  /\ vm_reserved h' = vm_reserved h /\ vm_limit h' = vm_limit h /\ vm_mmap_base h' = vm_mmap_base h
  /\ vm_brk h' = vm_brk h /\ vm_start_brk h' = vm_start_brk h
  /\ vm_noaccess h' = maps_subtract (vm_noaccess h) a (a + msz)
  /\ eager_used mo' + msz <= eager_used mo.

